// ▼▼▼ EDIT YOUR WATCHLIST HERE ▼▼▼
// US tickers are bare (AAPL), crypto is <SYM>-USD (BTC-USD), foreign uses the
// Yahoo suffix (VOD.L, 7203.T). One AlphaAI call is made per ticker.
const tickers = ['NVDA', 'AAPL', 'TSLA', 'MSFT', 'AMD'];
// ▲▲▲ EDIT YOUR WATCHLIST HERE ▲▲▲
return tickers.map(t => ({ json: { ticker: String(t).trim() } }));

// Build one HTML digest email from the per-ticker AlphaAI responses.
// Zips each HTTP response back to its ticker by index (n8n preserves order),
// keeps score≥7 news from the last WINDOW_H hours, dedupes by uid across days.

function slugify(text) {
  return (text || '').toLowerCase()
    .replace(/[^\w\s-]/g, '').replace(/\s+/g, '-').replace(/-+/g, '-').trim();
}
function dateForUrl(iso) {
  const d = new Date(iso);
  if (isNaN(d.getTime())) { return ''; }
  return String(d.getUTCMonth() + 1).padStart(2, '0') + '-' + String(d.getUTCDate()).padStart(2, '0');
}
function trunc(s, n) { s = (s == null ? '' : String(s)); return s.length > n ? s.slice(0, n - 1) + '…' : s; }
function esc(s) { return (s == null ? '' : String(s)).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); }

const SITE = 'https://alphai.io';
const WINDOW_H = 30;       // look-back window (a little over a day so nothing is missed)
const MAX_PER_TICKER = 5;

const responses = $input.all();
const wl = $('Watchlist').all();

const store = $getWorkflowStaticData('global');
store.sentUids = store.sentUids || [];
const seen = new Set(store.sentUids);

const now = Date.now();
const cutoff = now - WINDOW_H * 3600 * 1000;
const sections = [];
const newlySent = [];

for (let i = 0; i < responses.length; i++) {
  const ticker = (wl[i] && wl[i].json && wl[i].json.ticker) || '';
  const body = (responses[i] && responses[i].json) || {};
  const results = Array.isArray(body) ? body : (body.results || []);
  const rows = [];
  for (const a of results) {
    if (rows.length >= MAX_PER_TICKER) { break; }
    const org = a.original || {};
    const enr = a.enrichment || {};
    const uid = org.uid;
    if (!uid || seen.has(uid)) { continue; }
    const t = new Date(org.time_published || 0).getTime();
    if (isNaN(t) || t < cutoff) { continue; }
    const insights = enr.ai_trading_insights || {};
    const ia = ((insights.ticker_analysis || [])[0] || {}).impact_analysis || {};
    const sentiment = ia.sentiment || 'neutral';
    const color = sentiment === 'positive' ? '#1e9e5a' : sentiment === 'negative' ? '#d64541' : '#7a7a7a';
    const url = SITE + '/news/article/' + dateForUrl(org.time_published) + '/' + uid + '/' + slugify(org.title);
    const summary = esc(trunc(org.summary || ia.summary || '', 220));
    rows.push(
      '<tr><td style="padding:10px 0;border-bottom:1px solid #eee">' +
      '<a href="' + url + '" style="color:#0b6b3a;font-weight:600;text-decoration:none;font-size:15px">' +
      '[' + (enr.relevance_score || 0) + '] ' + esc(trunc(org.title || '', 140)) + '</a><br>' +
      '<span style="font-size:12px;color:#666"><b style="color:' + color + '">' + esc(sentiment) + '</b>' +
      ' · ' + esc(enr.category || 'news') + ' · ' + esc(org.source || org.source_domain || '') + '</span><br>' +
      '<span style="font-size:13px;color:#333">' + summary + '</span></td></tr>'
    );
    seen.add(uid);
    newlySent.push(uid);
  }
  if (rows.length === 0) { continue; }
  sections.push(
    '<h2 style="font-family:Arial,sans-serif;font-size:17px;margin:22px 0 4px;color:#111">' + esc(ticker) + '</h2>' +
    '<table style="width:100%;border-collapse:collapse">' + rows.join('') + '</table>'
  );
}

if (sections.length === 0) { return []; }

for (const u of newlySent) { store.sentUids.push(u); }
if (store.sentUids.length > 1000) { store.sentUids = store.sentUids.slice(-1000); }

const html =
  '<div style="max-width:640px;margin:0 auto;font-family:Arial,sans-serif;color:#111;padding:8px 4px">' +
  '<h1 style="font-size:20px;margin:0 0 2px">📈 AlphaAI watchlist digest</h1>' +
  '<p style="color:#666;font-size:13px;margin:0 0 6px">High-relevance news (score ≥ 7) from the last ' +
  WINDOW_H + 'h for your watchlist.</p>' +
  sections.join('') +
  '<p style="margin-top:26px;font-size:12px;color:#999">Powered by ' +
  '<a href="' + SITE + '" style="color:#0b6b3a">AlphaAI</a> — relevance-scored, ticker-linked financial news</p>' +
  '</div>';

const subject = 'AlphaAI watchlist — ' + sections.length + ' ticker' + (sections.length === 1 ? '' : 's') + ' with news today';

return [{ json: { html, subject } }];
